/**
 * @import {FileMetaData} from '../src/types.js'
 */

/**
 * Finds the row group that holds a row, and the row's offset inside that group.
 * Returns undefined when row is not a valid row index of the file.
 *
 * @param {FileMetaData} metadata
 * @param {number} row zero-based row index in the file
 * @returns {{ group: number, offset: number } | undefined}
 */
export function locateRow(metadata, row) {
  if (!Number.isInteger(row) || row < 0 || row >= Number(metadata.num_rows)) return undefined
  let groupStart = 0
  for (let group = 0; group < metadata.row_groups.length; group++) {
    const groupEnd = groupStart + Number(metadata.row_groups[group].num_rows)
    if (row < groupEnd) return { group, offset: row - groupStart }
    groupStart = groupEnd
  }
  return undefined
}

/**
 * Flags the row groups that hold at least one of the rows.
 * Rows that are not valid row indices of the file are ignored.
 *
 * @param {FileMetaData} metadata
 * @param {number[]} rows zero-based row indices in the file
 * @returns {boolean[]} one flag per row group
 */
export function groupsHolding(metadata, rows) {
  const included = Array(metadata.row_groups.length).fill(false)
  if (!rows.length) return included
  for (const row of rows) {
    const located = locateRow(metadata, row)
    if (located) included[located.group] = true
  }
  return included
}

